import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Tracing with OpenTelemetry","description":"Send a trace of every request Piwi serves, with each SQL statement it ran, to an OpenTelemetry collector you run.","frontmatter":{"title":"Tracing with OpenTelemetry","description":"Send a trace of every request Piwi serves, with each SQL statement it ran, to an OpenTelemetry collector you run.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/tracing.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/tracing.html"}],["meta",{"property":"og:title","content":"Tracing with OpenTelemetry | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Send a trace of every request Piwi serves, with each SQL statement it ran, to an OpenTelemetry collector you run."}]]},"headers":[],"relativePath":"operate/tracing.md","filePath":"operate/tracing.md","lastUpdated":1791472319000}'),i={name:"operate/tracing.md"};function o(n,e,d,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="tracing-with-opentelemetry" tabindex="-1">Tracing with OpenTelemetry <a class="header-anchor" href="#tracing-with-opentelemetry" aria-label="Permalink to &quot;Tracing with OpenTelemetry&quot;">​</a></h1><p>Piwi can send a trace of each request it serves to an OpenTelemetry collector: one span per request, one per request the server makes to itself while it renders a page, and one per SQL statement, with its text. When a page is slow, the trace names the statements that made it slow and the data call that ran them.</p><p>Tracing is <strong>off by default</strong>. It starts when you name a collector, and traces go to that endpoint only, so it does not change the &quot;zero telemetry&quot; promise.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>Point the standard OTLP variable at your collector&#39;s OTLP/HTTP endpoint, in the environment of the Piwi container or your <code>.env</code> file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OTEL_EXPORTER_OTLP_ENDPOINT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://otel-collector:4318</span></span></code></pre></div><p>Piwi exports OTLP over HTTP, as JSON. The other standard variables apply as the OpenTelemetry SDK defines them:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Use</th></tr></thead><tbody><tr><td><code>OTEL_EXPORTER_OTLP_TRACES_ENDPOINT</code></td><td>The traces endpoint alone, in place of <code>OTEL_EXPORTER_OTLP_ENDPOINT</code></td></tr><tr><td><code>OTEL_EXPORTER_OTLP_HEADERS</code></td><td>Headers for the collector, such as an API key (<code>x-api-key=…</code>)</td></tr><tr><td><code>OTEL_SERVICE_NAME</code>, <code>OTEL_RESOURCE_ATTRIBUTES</code></td><td>How the traces are labeled; the service is <code>piwi</code> by default</td></tr><tr><td><code>OTEL_TRACES_SAMPLER</code>, <code>OTEL_TRACES_SAMPLER_ARG</code></td><td>Keep a share of the traces: <code>parentbased_traceidratio</code> and <code>0.1</code> keep 10 %</td></tr><tr><td><code>OTEL_BSP_SCHEDULE_DELAY</code>, <code>OTEL_BSP_MAX_QUEUE_SIZE</code></td><td>How spans are batched before they are sent</td></tr><tr><td><code>OTEL_SDK_DISABLED</code></td><td><code>true</code> turns tracing off again</td></tr></tbody></table><h2 id="what-a-trace-holds" tabindex="-1">What a trace holds <a class="header-anchor" href="#what-a-trace-holds" aria-label="Permalink to &quot;What a trace holds&quot;">​</a></h2><ul><li><strong>A span per request</strong>, named after its method and path (<code>GET /projects/12</code>), with its status code. A request that arrives with a <code>traceparent</code> header continues that trace.</li><li><strong>An internal span per request the server makes to itself</strong> while rendering a page, one per data call, under the page&#39;s span, so a slow page shows which of its data calls is slow.</li><li><strong>A span per SQL statement</strong>, with the statement as Drizzle sent it (<code>db.statement</code>, parameters as placeholders, never their values). PostgreSQL traces every statement, transactions included; SQLite every statement outside a transaction.</li></ul><p>Each page response names its trace in a <code>Server-Timing: traceparent</code> header, which the browser&#39;s developer tools show beside the request.</p><h2 id="looking-at-traces-on-your-machine" tabindex="-1">Looking at traces on your machine <a class="header-anchor" href="#looking-at-traces-on-your-machine" aria-label="Permalink to &quot;Looking at traces on your machine&quot;">​</a></h2><p>Jaeger accepts OTLP and shows traces in the browser:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 16686:16686</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 4318:4318</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jaegertracing/all-in-one:latest</span></span></code></pre></div><p>Start Piwi with <code>OTEL_EXPORTER_OTLP_ENDPOINT=http://localhost:4318</code> and open <code>http://localhost:16686</code>.</p>',15)])])}const T=t(i,[["render",o]]);export{g as __pageData,T as default};
